-- Run against a migrated test database. All synthetic rows and accounts roll back.
begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();t uuid:=gen_random_uuid();c public.pv_config_packages;prior integer;n integer;cid uuid;body jsonb:=$body${"schema":1,"engine":"config-draft-v1","title":"New configuration assessment","profile":{"system":"argus","version":"8.x verified in environment","environment":"Validation","company":"Synthetic Pharma","companyId":"synthetic","markets":"US","modules":"","customizations":""},"rules":[{"key":"R1","country":"country baseline","license":"license baseline","destination":"destination baseline","clockStart":"clockStart baseline","days":"15","dayType":"dayType baseline","format":"format baseline","condition":"condition baseline","scheduling":"scheduling baseline","priority":"priority baseline"}],"baselineStatus":"confirmed","area":"reporting","source":{"title":"Synthetic guidance","url":"https://www.fda.gov/synthetic","edition":"Synthetic version 1","location":"Section 2","excerpt":"Synthetic requirement text for configuration testing only.","authority":"primary","verified":true},"applicability":"relevant","rationale":"Applies to the synthetic configured scope.","proposal":{"baselineKey":"R1","rule":{"key":"R1","country":"country baseline","license":"license baseline","destination":"destination baseline","clockStart":"clockStart baseline","days":"7","dayType":"dayType baseline","format":"format baseline","condition":"condition baseline","scheduling":"scheduling baseline","priority":"priority baseline"},"change":"Synthetic timeframe change for testing only."},"implementation":"Implement in validation; preserve baseline export; rollback if regression fails.","generated":{"engine":"config-draft-v1","classification":"UNVERIFIED CONFIGURATION DRAFT — not a vendor import file","mapping":{"url":"https://docs.oracle.com/health-sciences/argus-safety-811/AADMN/businessconfig.htm","note":"Argus field prompts: expedited reporting rules and destination dependencies. Confirm labels, available settings and behavior against your installed release."},"baseline":{"key":"R1","country":"country baseline","license":"license baseline","destination":"destination baseline","clockStart":"clockStart baseline","days":"15","dayType":"dayType baseline","format":"format baseline","condition":"condition baseline","scheduling":"scheduling baseline","priority":"priority baseline"},"diff":[{"field":"days","label":"Reporting timeframe (days)","before":"15","after":"7"}],"gaps":[],"requirements":[{"kind":"Business","text":"Apply Synthetic guidance to Synthetic Pharma in US only after applicability review."},{"kind":"System","text":"Synthetic timeframe change for testing only."},{"kind":"Data","text":"Review destination, product/license and reference-data dependencies, null/missing values and mapping exceptions."},{"kind":"Process","text":"Update SOP/training and change control where affected. Implement in validation; preserve baseline export; rollback if regression fails."}],"tests":[{"id":"T01","scenario":"Positive match","input":"Synthetic case satisfying: condition baseline","expected":"Confirm expected destination destination baseline and format format baseline."},{"id":"T02","scenario":"Negative match","input":"Synthetic case outside one specified eligibility condition; repeat for each condition and exception.","expected":"Reviewer specifies which report must not schedule and any alternative obligation."},{"id":"T03","scenario":"Clock boundary","input":"Synthetic receipt at day-zero boundary; test timezone, holidays and 7 dayType baseline.","expected":"Reviewer calculates an exact due timestamp independently from the source."},{"id":"T04","scenario":"Follow-up / upgrade / downgrade","input":"Synthetic follow-up changes seriousness, expectedness or relatedness; include previously submitted cases.","expected":"Reviewer specifies new, changed or suppressed reporting obligations."},{"id":"T05","scenario":"Overlap and regression","input":"Synthetic case matching this rule and another active rule; include unaffected markets and products.","expected":"Reviewer confirms precedence, duplicate handling and unchanged obligations."}],"limitations":["No case execution, due-date simulation or automatic legal interpretation is performed.","Complete the synthetic inputs and exact expected outputs before using these draft scenarios as a test protocol.","System mapping is a field guide, not a verified release-specific adapter.","Gap results cover the selected source and entered configuration only; they do not establish regulatory completeness."]}}$body$::jsonb;
begin
 insert into auth.users(id) values(a),(b),(outsider);
 insert into public.teams(id,name,created_by) values(t,'Synthetic configuration QA',a);
 insert into public.team_members(team_id,user_id,role) values(t,a,'owner'),(t,b,'owner');
 execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 c:=public.save_pv_config_package(null,0,t,'save',body,'Synthetic draft');prior:=c.revision;
 if c.state<>'draft' then raise exception 'Draft state missing';end if;
 begin perform public.save_pv_config_package(c.id,0,t,'save',body,'Stale edit');raise exception 'Stale edit accepted';exception when raise_exception then if sqlerrm='Stale edit accepted' then raise;end if;end;
 c:=public.save_pv_config_package(c.id,c.revision,t,'submit','{}','Synthetic submit');
 begin perform public.save_pv_config_package(c.id,c.revision,t,'approve','{}','Self approve');raise exception 'Self approval accepted';exception when raise_exception then if sqlerrm='Self approval accepted' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);
 select count(*) into n from public.pv_config_packages where id=c.id;if n<>0 then raise exception 'Private package leaked';end if;
 select count(*) into n from public.pv_config_revisions where package_id=c.id;if n<>0 then raise exception 'Private revisions leaked';end if;
 begin perform public.save_pv_config_package(c.id,c.revision,t,'rework','{}','Unauthorized edit');raise exception 'Unauthorized edit accepted';exception when raise_exception then if sqlerrm='Unauthorized edit accepted' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 c:=public.save_pv_config_package(c.id,c.revision,t,'approve','{}','Independent synthetic approval');if c.state<>'approved' then raise exception 'Approval missing';end if;
 begin perform public.save_pv_config_package(c.id,c.revision,t,'save',body,'Overwrite approved');raise exception 'Approved overwrite accepted';exception when raise_exception then if sqlerrm='Approved overwrite accepted' then raise;end if;end;
 begin update public.pv_config_revisions set reason='Overwrite' where package_id=c.id;raise exception 'History write accepted';exception when insufficient_privilege then null;end;
 c:=public.save_pv_config_package(c.id,c.revision,t,'handoff','{}','Synthetic implementation handoff');cid:=c.case_id;
 c:=public.save_pv_config_package(c.id,c.revision,t,'handoff','{}','Repeat handoff');if c.case_id<>cid then raise exception 'Duplicate handoff created';end if;
 select count(*) into n from public.company_cases where id=cid and team_id=t;if n<>1 then raise exception 'Scoped handoff missing';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','pv_pending')::text,true);
 begin perform public.save_pv_config_package(null,0,null,'save',body,'Pending account');raise exception 'Pending write accepted';exception when raise_exception then if sqlerrm='Pending write accepted' then raise;end if;end;
 raise notice 'Configuration database checks passed: concurrency, scopes, approval, immutability, handoff and pending denial';
end $test$;
rollback;
